package com.earthtrip.expense.adapter.in.web.api.v1.trips.by_trip_id.settlements.by_settlement_id.closures;import com.earthtrip.expense.application.port.in.SettlementUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/settlements/{settlementId}/closures") class SettlementClosuresController{private final SettlementUseCase useCase;private final CurrentActor actor;SettlementClosuresController(SettlementUseCase u,CurrentActor a){useCase=u;actor=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED)SettlementUseCase.SettlementResult post(@PathVariable UUID tripId,@PathVariable UUID settlementId,@Valid @RequestBody ClosureMutation r){return useCase.close(tripId,settlementId,actor.requireUserId(),r.baseVersion(),r.paymentsConfirmed());}}
record ClosureMutation(@Min(0)long baseVersion,@AssertTrue boolean paymentsConfirmed){}
